function isDemonstrationMode(){try{return window.TeplitsaWarehouseBootstrap?window.TeplitsaWarehouseBootstrap.isDemo():localStorage.getItem(DEMO_MODE_FLAG_KEY)==='1'}catch{return false}}
function activeWarehouseAllowsBuiltinCatalog(){
  if(isDemonstrationMode())return true;
  const bootstrap=window.TeplitsaWarehouseBootstrap;
  if(!bootstrap)return true;
  const registry=bootstrap.getRegistry?.(),active=bootstrap.activeWarehouse?.(),primary=registry?.warehouses?.[0];
  return Boolean(active&&primary&&String(active.id)===String(primary.id)&&active.catalogMode==='catalog');
}
function warehouseRouteStartReady(){
  const point=settings?.warehouse||{},lat=Number(point.lat),lon=Number(point.lon);
  return Boolean(String(point.address||'').trim())&&Number.isFinite(lat)&&lat>=-90&&lat<=90&&Number.isFinite(lon)&&lon>=-180&&lon<=180;
}
function resolveDataStorageKey(key){try{return window.TeplitsaWarehouseBootstrap?window.TeplitsaWarehouseBootstrap.dataKey(key,isDemonstrationMode()?'demo':'live'):isDemonstrationMode()?DEMO_STORAGE_PREFIX+key:key}catch{return key}}
