  for(const id of Object.keys(routeAssignments))if(!orderIds.has(id)){delete routeAssignments[id];changed=true}
  for(const [id,routeId]of Object.entries(routeLocks))if(!orderIds.has(id)||!routeId||routeAssignments[id]!==routeId){delete routeLocks[id];changed=true}
  if(changed){persistRouteAssignments();persistRouteLocks()}
