function reportRuntimeBoundary(kind,area,error){
  const message=String(error?.message||error||'Неизвестная ошибка');
  if(resizeObserverNoise(message)){console.debug('ResizeObserver notification skipped',{area,message});return null}
  const incidentId=runtimeIncidentId();
  console.error(`[${incidentId}] ${kind}: ${area}`,error);
  window.reportRuntimeErrorV783?.(`${kind}.${area}`,error);
  const network=runtimeNetworkFailure(message);
  showAppHealth(
    network?'Не удалось связаться с сервисом':'Не удалось завершить действие',
    network
      ? `Проверьте подключение и повторите действие. Код события: ${incidentId}.`
      : `Результат операции не подтверждён. Обновите раздел и проверьте данные. Код события: ${incidentId}.`
  );
  return incidentId
}
function safeUi(area,fn){try{return fn()}catch(err){appErrorCount++;reportRuntimeBoundary('ui',area,err);return null}}
