function ordersPaginationItems(current,total){if(total<=7)return Array.from({length:total},(_,i)=>i+1);const items=[1],from=Math.max(2,current-1),to=Math.min(total-1,current+1);if(from>2)items.push('…');for(let page=from;page<=to;page++)items.push(page);if(to<total-1)items.push('…');items.push(total);return items}
