  $('deliveryCalcSub').textContent=manualMode==='fixed'?'Ручная сумма действует только для этого заказа; маршрут и расстояние сохраняются':'Программа использует настройки активного склада и дорожное расстояние до клиента';
  $('deliveryModeBadge').className='badge '+(manualMode==='fixed'?'badge-warn':'badge-green');
