  if(manualMode==='fixed'&&document.activeElement!==$('manualDeliveryCost'))$('manualDeliveryCost').value=String(Math.round(Number(deliveryCalculation.cost||0)*100)/100);
  const tariff=$('deliveryCalcBox')?.querySelector('.delivery-calc-grid .delivery-calc-cell:nth-child(2) b');if(tariff)tariff.textContent=manualMode==='fixed'?'По заказу':automaticLabel;
  $('deliveryCalcStatus').textContent=message||(deliveryCalculation.calculating?'Рассчитываю автомобильный маршрут от склада…':deliveryCalculation.error?deliveryCalculation.error:manualMode==='fixed'?'Ручная сумма будет сохранена только для этого заказа.':deliveryCalculation.distanceKm?`${deliveryCalculation.source}.`:'Выберите точный адрес — доставка рассчитается автоматически.');
