async function calculateDeliveryForGeo__baseV595(g){
  if(!g||!Number.isFinite(Number(g.lat))||!Number.isFinite(Number(g.lon))){resetDeliveryCalculation();return}
  if(!warehouseRouteStartReady()){deliveryCalculation={distanceKm:0,cost:0,autoCost:0,source:'',calculating:false,error:'Сначала подтвердите адрес и точку активного склада в разделе «Настройки программы → Склады».',manual:false,manualMode:'auto',pricingMode:deliveryPricingConfig().pricingMode,radiusKm:0};renderDeliveryCalculation();return deliveryCalculation}
  const token=++deliveryCalcToken;
  deliveryCalculation={distanceKm:0,cost:0,autoCost:0,source:'',calculating:true,error:'',manual:false,manualMode:'auto',pricingMode:deliveryPricingConfig().pricingMode,radiusKm:0};
  renderDeliveryCalculation('Рассчитываю расстояние по автомобильным дорогам от склада…');
  const run=(async()=>{
    let km=0,source='';
    try{const route=await osrmRoute([{lat:Number(settings.warehouse.lat),lon:Number(settings.warehouse.lon)},{lat:Number(g.lat),lon:Number(g.lon)}]);km=Number(route.distance||0)/1000;source='Точный дорожный расчёт OSRM / OpenStreetMap'}
    catch(err){km=haversine(settings.warehouse,{lat:Number(g.lat),lon:Number(g.lon)})*1.28;source='Резервная оценка по прямой с дорожным коэффициентом';if(!Number.isFinite(km)||km<=0)throw err}
    if(token!==deliveryCalcToken)return;
    km=Math.max(0,Math.round(km*10)/10);
    const cfg=deliveryPricingConfig(),radiusKm=haversine(settings.warehouse,{lat:Number(g.lat),lon:Number(g.lon)}),autoCost=standaloneDeliveryPrice(km,cfg,radiusKm),modeSource=cfg.pricingMode==='fixed'?'фиксированная цена склада':cfg.pricingMode==='radius'&&cfg.radiusZones.some(zone=>radiusKm<=zone.radiusKm)?`тарифная зона ${radiusKm.toLocaleString('ru-RU',{maximumFractionDigits:1})} км от склада`:'подача, точка и километры по правилам склада';
    deliveryCalculation={distanceKm:km,cost:autoCost,autoCost,source:`${source} · ${modeSource}`,calculating:false,error:'',manual:false,manualMode:'auto',pricingMode:cfg.pricingMode,radiusKm};
    renderDeliveryCalculation()
  })().catch(err=>{if(token!==deliveryCalcToken)return;deliveryCalculation={distanceKm:0,cost:0,autoCost:0,source:'',calculating:false,error:'Не удалось рассчитать доставку: '+(err?.message||'ошибка маршрута'),manual:false,manualMode:'auto',pricingMode:deliveryPricingConfig().pricingMode,radiusKm:0};renderDeliveryCalculation()});
  deliveryCalcPromise=run;return run
}

