  const purchaseMap=new Map();let purchaseSpend=0,purchaseUnits=0,writeoffCost=0,writeoffUnits=0,returnUnits=0;for(const m of inventoryMovements){if(!reportDateInRange(m.date,period))continue;const product=products.find(p=>p.id===m.productId),qty=Math.max(0,Number(m.qty||Math.abs(m.delta)||0)),unitCost=Math.max(0,Number(m.unitCost||0))||reportProductBaseCost(m.productId,m.date).cost;if(m.type==='receipt'){const spend=qty*unitCost,key=`${m.productId}|${m.counterparty||product?.supplier||'Поставщик не указан'}`,row=purchaseMap.get(key)||{productId:m.productId,name:product?.name||'Удалённый товар',article:product?.article||'',unit:product?.unit||'шт',supplier:m.counterparty||product?.supplier||'Поставщик не указан',qty:0,spend:0,operations:0};row.qty+=qty;row.spend+=spend;row.operations++;purchaseMap.set(key,row);purchaseSpend+=spend;purchaseUnits+=qty}else if(m.type==='writeoff'){writeoffCost+=qty*unitCost;writeoffUnits+=qty}else if(m.type==='return')returnUnits+=qty}
