  const employeeRows=reportEmployeeRows(period),expenseRows=reportExpenseRows(period),payroll=employeeRows.reduce((s,x)=>s+x.cost,0),payrollContributions=payroll*Number(reportingData.settings.payrollContribPct||0)/100,extraExpenses=expenseRows.reduce((s,x)=>s+x.cost,0);
  const expenseCategoryMap=new Map();for(const x of expenseRows)expenseCategoryMap.set(x.category,(expenseCategoryMap.get(x.category)||0)+x.cost);const expenseCategoryRows=[...expenseCategoryMap].map(([name,cost])=>({name,cost})).sort((a,b)=>b.cost-a.cost);
