function directorRouteDetails(r){return r.routeRows.map(route=>{const archive=(typeof routeArchives!=='undefined'?routeArchives:[]).find(x=>x.id===route.id),plan=asObject(archive?.planSnapshot||routePlans[route.id]),plannedKm=Math.max(0,Number(plan.distance||0))/1000,actualKm=route.closed?Math.max(0,Number(archive?.actualKm||route.distanceKm)):route.distanceKm,varianceKm=actualKm-plannedKm,costPerKm=actualKm?route.payment/actualKm:0,incomePerKm=actualKm?route.deliveryRevenue/actualKm:0,marginPct=route.deliveryRevenue?route.profit/route.deliveryRevenue*100:0;let reason='Доход от доставки покрывает оплату водителя',action='Контроль не требуется',tone='good';if(route.driver==='Не назначен'){reason='Водитель не назначен';action='Назначить водителя до выпуска';tone='bad'}else if(route.profit<0&&route.deliveryRevenue<=0){reason='Клиентам не начислена доставка';action='Проверить цены доставки в заказах';tone='bad'}else if(route.profit<0&&route.orders<=2){reason='Мало точек при высокой стоимости рейса';action='Объединить с другим рейсом или согласовать убыток';tone='bad'}else if(route.profit<0){reason='Оплата водителю выше дохода доставки';action='Проверить тариф, километры и распределение доставки';tone='bad'}else if(route.deliveryRevenue&&marginPct<15){reason='Низкий запас рентабельности доставки';action='Проверить тариф перед повторением рейса';tone='warn'}else if(route.closed&&plannedKm&&varianceKm>plannedKm*.15){reason='Фактический пробег существенно выше плана';action='Уточнить причину отклонения у логиста';tone='warn'}return{...route,plannedKm,actualKm,varianceKm,costPerKm,incomePerKm,marginPct,reason,action,tone}})}

