function directorCostSources(r){const map=new Map();for(const slice of r.slices)for(const item of slice.items){let source='Нет цены',known=false,cost=0;if(reportingData.settings.costMethod==='smart'&&Number(item.purchasePrice)>0){source='Историческая цена в заказе';known=true;cost=Number(item.purchasePrice)*Number(item.qty||0)}else{const info=reportProductBaseCost(item.productId||'',slice.date);source=info.source||'Нет цены';known=info.known;cost=info.cost*Number(item.qty||0)}const row=map.get(source)||{source,lines:0,cost:0,known};row.lines++;row.cost+=cost;row.known&&=known;map.set(source,row)}return[...map.values()].sort((a,b)=>b.cost-a.cost)}

