function syncReportExpenseMode(){const monthly=$('reportExpenseMode')?.value==='monthly';if($('reportExpenseDateField'))$('reportExpenseDateField').style.display=monthly?'none':'block';if($('reportExpenseFromField'))$('reportExpenseFromField').style.display=monthly?'block':'none';if($('reportExpenseToField'))$('reportExpenseToField').style.display=monthly?'block':'none'}
