function saveReportExpense(event){event.preventDefault();const id=$('reportExpenseEditId').value,mode=$('reportExpenseMode').value==='monthly'?'monthly':'one_time',expense={id:id||uuid(),name:$('reportExpenseName').value.trim(),category:$('reportExpenseCategory').value||'Прочее',amount:Math.max(0,Number($('reportExpenseAmount').value||0)),mode,date:mode==='one_time'?($('reportExpenseDate').value||todayISO()):'',activeFrom:mode==='monthly'?$('reportExpenseFrom').value:'',activeTo:mode==='monthly'?$('reportExpenseTo').value:'',note:$('reportExpenseNote').value.trim(),enabled:true};if(!expense.name){alert('Укажите название расхода.');return}if(expense.activeFrom&&expense.activeTo&&expense.activeFrom>expense.activeTo){alert('Начало действия расхода не может быть позже окончания.');return}if(id)reportingData.expenses=reportingData.expenses.map(x=>x.id===id?expense:x);else reportingData.expenses.push(expense);reportingData=normalizeReportingData(reportingData);persistReporting();resetReportExpenseForm();refreshAllReportBounds();renderReport();renderReportExpenses()}
