async function deleteReportExpense(id){const x=reportingData.expenses.find(e=>e.id===id);if(!x||!await jfConfirm(`Удалить расход «${x.name}»?`))return;reportingData.expenses=reportingData.expenses.filter(e=>e.id!==id);persistReporting();resetReportExpenseForm();refreshAllReportBounds();renderReport();renderReportExpenses()}
