function printReport(){const r=buildDirectorReport(calculateReport()),periodLabel=`${formatDateOnly(r.period.fromISO)} — ${formatDateOnly(r.period.toISO)}`,actions=r.actions.slice(0,20).map(x=>`<tr><td>${escapeHtml(directorPriorityLabel(x.priority))}</td><td><b>${escapeHtml(x.object)}</b><br><small>${escapeHtml(x.fact)}</small></td><td>${escapeHtml(x.owner)}</td><td>${escapeHtml(x.action)}</td><td class="money">${x.amount?money(x.amount):'—'}</td></tr>`).join(''),routes=r.routeDetails.slice(0,15).map(x=>`<tr><td>${formatDateOnly(x.date)}<br><small>${escapeHtml(x.name)}</small></td><td>${escapeHtml(x.driver)}</td><td class="num">${x.orders}</td><td class="money">${money(x.profit)}</td><td>${escapeHtml(x.reason)}</td></tr>`).join('');$('printArea').innerHTML=`<div class="print-sheet print-route-sheet"><div class="print-header"><div><div class="print-brand-name">ТЕПЛИЦА78 · ОТЧЁТ ДИРЕКТОРА</div><div class="director-print-title">Управленческая сводка</div></div><div class="print-doc-box"><div class="print-doc-type">Период</div><div class="print-doc-number" style="font-size:14px">${periodLabel}</div><div class="print-doc-status">Версия ${APP_VERSION}</div></div></div><div class="print-alert"><b>${escapeHtml(r.verdictTitle)}</b><br>${escapeHtml(r.verdictText)}</div><div class="director-print-summary"><div class="print-cell"><span>Выручка</span><b>${money(r.revenue)}</b></div><div class="print-cell"><span>Чистая прибыль</span><b>${money(r.netProfit)}</b></div><div class="print-cell"><span>Денежный поток</span><b>${money(r.cashResult)}</b></div><div class="print-cell"><span>Дебиторка</span><b>${money(r.debtTotal)}</b></div></div><div class="print-section"><div class="print-section-title">Ключевые факты</div><div class="print-grid"><div class="print-cell"><span>Незакрытая работа</span><b>${r.backlog.length} · ${money(r.expectedRevenue)}</b></div><div class="print-cell"><span>Просрочено</span><b>${r.overdue.length}</b></div><div class="print-cell"><span>Авансы</span><b>${money(r.advanceTotal)}</b></div><div class="print-cell"><span>Вернуть клиентам</span><b>${money(r.refundLiability)}</b></div><div class="print-cell"><span>Убыток рейсов</span><b>${money(r.routeLossTotal)}</b></div><div class="print-cell"><span>Склад на конец</span><b>${money(r.stock.closingValue)}</b></div><div class="print-cell"><span>Риски склада</span><b>${r.stock.deficit+r.stock.out+r.stock.low}</b></div><div class="print-cell"><span>Достоверность</span><b>${r.reliabilityLabel} · ${r.reliabilityScore}/100</b></div></div></div><div class="print-section"><div class="print-section-title">Что требует решения${r.actions.length>20?' — первые 20':''}</div><table class="print-table"><thead><tr><th>Приоритет</th><th>Проблема</th><th>Ответственный</th><th>Действие</th><th class="money">Риск</th></tr></thead><tbody>${actions||'<tr><td colspan="5">Незакрытых действий нет</td></tr>'}</tbody></table></div><div class="print-section"><div class="print-section-title">Экономика рейсов${r.routeDetails.length>15?' — первые 15':''}</div><table class="print-table"><thead><tr><th>Дата / рейс</th><th>Водитель</th><th class="num">Заказов</th><th class="money">Результат</th><th>Почему</th></tr></thead><tbody>${routes||'<tr><td colspan="5">Рейсов нет</td></tr>'}</tbody></table></div><div class="print-footnote"><span>Сформировано системой «Заказы и логистика»</span><span>${formatDateTime(new Date().toISOString())}</span></div></div>`;doPrint()}

