importBackupFile__implV595=async function(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;try{const parsed=JSON.parse(await file.text()),data=asObject(parsed.data||parsed);if(!Array.isArray(data.orders)||!Array.isArray(data.products)||!Array.isArray(data.drivers))throw new Error('Файл не содержит обязательные разделы');if(!await jfConfirm('Восстановить данные из выбранной резервной копии? Текущая база будет заменена.'))return;exportBackup();orders=asArray(data.orders).map(normalizeOrder);products=asArray(data.products).map(normalizeProduct);inventoryMovements=asArray(data.inventoryMovements).map(normalizeInventoryMovement).filter(Boolean);drivers=asArray(data.drivers).map(normalizeDriver);settings=deepMerge(cloneValue(DEFAULTS),asObject(data.settings));settings.routeMode=settings.routeMode==='oneway'?'oneway':'round';settings.returnToDepot=settings.routeMode==='round';settings.driverPayment=normalizeDriverPaymentConfig(settings);settings.deliveryPricing=normalizeDeliveryPricingConfig(settings.deliveryPricing);routePlans=asObject(data.routePlans);routeAssignments=asObject(data.routeAssignments);routeCatalog=asObject(data.routeCatalog);routeDriverAssignments=asObject(data.routeDriverAssignments);routeLocks=asObject(data.routeLocks);routeOverrides=asObject(data.routeOverrides);routeExecutions=asObject(data.routeExecutions);routeArchives=asArray(data.routeArchives);warehouseReservations=asObject(data.warehouseReservations);reportingData=normalizeReportingData(data.reportingData||{});persistOrders();persistProducts();persistInventoryMovements();persistDrivers();persistSettings();persistRoutes();persistRouteAssignments();persistRouteDrivers();persistRouteLocks();persistRouteOverrides();persistRouteExecutions();persistRouteArchives();persistWarehouseReservations();persistReporting();runDataDiagnostics(false);renderAll();alert('Резервная копия восстановлена: заказы, склад, статусы, рейсы, оплаты и архив загружены.')}catch(err){alert('Не удалось загрузить резервную копию: '+(err?.message||err))}};

exportCSV__implV595=function(){if(!orders.length){alert('Нет заказов для экспорта.');return}const rows=[['Номер','Тип','Создан','Дата','Статус выполнения','Статус склада','Статус оплаты','Архив','Закрыт','Требуется действие','Попыток доставки','Контакт','Связь','Адрес / выдача','Область','Район','Товары','Сумма товаров','Доставка ₽','Итого ₽']];orders.forEach(o=>rows.push([o.number,isPickup(o)?'Самовывоз':'Доставка',formatDateTime(o.createdAt),o.deliveryDate,fulfillmentLabel(o.fulfillmentStatus),warehouseFlowLabel(o.warehouseFlowStatus),paymentStatusLabel(o.paymentStatus),o.archived?'Да':'Нет',o.closedAt?formatDateTime(o.closedAt):'',o.requiresAction||'',asArray(o.deliveryAttempts).length,isPickup(o)?'':o.contactName,isPickup(o)?'':o.contactMethod,isPickup(o)?settings.warehouse.address:o.deliveryAddress,isPickup(o)?'':orderRegion(o),isPickup(o)?'':orderDistrict(o),o.items.map(i=>`${i.name} x${i.qty}`).join('; '),goodsTotalOf(o),deliveryCostOf(o),orderGrandTotal(o)]));const csv=rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(';')).join('\n');downloadBlob('\ufeff'+csv,`orders-smart-statuses-${todayISO()}.csv`,'text/csv;charset=utf-8')};

/* ===== FULL AUDIT STABILITY PATCH v5.0.1 ===== */
runDataDiagnostics__implV595=function(showResult=false){
  if(activeWarehouseAllowsBuiltinCatalog())products=mergeBuiltinCatalog(products);
  let fixes=runDataDiagnostics__baseV595(false);
  reportingData=normalizeReportingData(reportingData);persistReporting();
  for(const id of Object.keys(routeOverrides))if(!routeCatalog[id]&&!routePlans[id]&&!Object.values(routeAssignments).includes(id))delete routeOverrides[id];persistRouteOverrides();

  let changed=false;const orderIds=new Set(orders.map(o=>o.id)),invalidated=new Set();
  for(const id of Object.keys(warehouseReservations))if(!orderIds.has(id)||orders.find(o=>o.id===id)?.fulfillmentStatus!=='pickup_ready'){delete warehouseReservations[id];fixes++;changed=true}
  for(const[routeId,execution]of Object.entries(routeExecutions)){
    const before=asArray(execution.orderIds).length;execution.orderIds=asArray(execution.orderIds).filter(id=>orderIds.has(id));
    if(execution.orderIds.length!==before){fixes++;changed=true}
    if(!execution.orderIds.length||!['in_transit','awaiting_close'].includes(execution.status)){delete routeExecutions[routeId];fixes++;changed=true}
  }
  for(const order of orders){
    const routeId=routeAssignments[order.id]||routeLocks[order.id];
    if((order.archived||isTerminalOrder(order))&&routeId){delete routeAssignments[order.id];delete routeLocks[order.id];invalidated.add(routeId);fixes++;changed=true}
    if(['in_transit','awaiting_close'].includes(order.fulfillmentStatus)&&!Object.values(routeExecutions).some(x=>asArray(x.orderIds).includes(order.id))){setOrderFulfillment(order,'not_delivered','Исправлен незакрытый статус','Активный рейс для заказа не найден; товар считается возвращённым на склад');order.warehouseFlowStatus='returned';order.requiresAction='retry_or_cancel';fixes++;changed=true}
    const wasArchived=order.archived,wasPayment=order.paymentStatus;evaluateAutoArchive(order);if(wasArchived!==order.archived||wasPayment!==order.paymentStatus)changed=true
  }
  for(const routeId of invalidated){delete routePlans[routeId];delete routeDriverAssignments[routeId];if(!Object.values(routeAssignments).includes(routeId))delete routeCatalog[routeId]}
  if(changed){persistOrders();persistRouteAssignments();persistRouteLocks();persistRouteDrivers();persistRoutes();persistRouteExecutions();persistRouteArchives();persistWarehouseReservations()}

  changed=false;const affectedRoutes=new Set();
  for(const order of orders){
    const routeId=String(routeAssignments[order.id]||routeLocks[order.id]||'');
    const closedOutsideRoute=order.archived||['delivered','partial','not_delivered','not_relevant','pickup_collected'].includes(order.fulfillmentStatus);
    if(routeId&&routeId!=='__unassigned__'&&closedOutsideRoute&&!routeExecutionActive(routeId)){
      delete routeAssignments[order.id];delete routeLocks[order.id];releaseWarehouseReservation(order.id);affectedRoutes.add(routeId);fixes++;changed=true
    }
    if(order.fulfillmentStatus==='not_delivered'){
      if(order.warehouseFlowStatus!=='returned'){order.warehouseFlowStatus='returned';changed=true;fixes++}
      if(order.requiresAction!=='retry_or_cancel'){order.requiresAction='retry_or_cancel';changed=true}
    }
    if(order.fulfillmentStatus==='partial'&&!order.fulfillmentResult?.resolution){
      if(order.warehouseFlowStatus!=='returned'){order.warehouseFlowStatus='returned';changed=true;fixes++}
      if(order.requiresAction!=='partial_resolution'){order.requiresAction='partial_resolution';changed=true}
    }
  }
  for(const routeId of affectedRoutes){
    const stillAssigned=Object.values(routeAssignments).includes(routeId),stillExecuting=routeExecutionActive(routeId);
    if(!stillAssigned&&!stillExecuting){delete routePlans[routeId];delete routeDriverAssignments[routeId];delete routeCatalog[routeId];delete routeOverrides[routeId]}
  }
  if(changed){persistOrders();persistRouteAssignments();persistRouteLocks();persistRouteDrivers();persistRoutes();persistRouteOverrides();persistWarehouseReservations()}
  const msg=fixes?`Проверка завершена. Исправлено проблем: ${fixes}.`:'Проверка завершена. Ошибок в базе не обнаружено.';
  if($('diagnosticStatus'))$('diagnosticStatus').textContent=`Версия системы: ${APP_VERSION} · ${msg}`;if(showResult)alert(msg);return fixes
};

document.addEventListener('leafletready',()=>safeUi('Подключение карт',()=>{
  for(const id of['orderMap','warehouseMap','routesMap']){const el=$(id);if(el?.dataset.mapError){delete el.dataset.mapError;el.innerHTML=''}}
  const view=activeView();if(view==='settings')ensureWarehouseMap();if(view==='trips')ensureRoutesMap();if($('orderModal')?.classList.contains('open'))ensureOrderMap();
}));
/* ===== END FULL AUDIT STABILITY PATCH ===== */

clearAll__implV595=async function(){if(!orders.length)return;if(Object.keys(routeExecutions).some(routeExecutionActive)){alert('Нельзя удалить базу, пока есть незакрытый рейс. Сначала обработайте возврат машины.');return}if(!await jfConfirm('Безвозвратно удалить все заказы, маршруты, закрытые рейсы, статусы и блокировки? Товары и складские движения сохранятся.'))return;orders=[];routeAssignments={};routeCatalog={};routeDriverAssignments={};routeLocks={};routePlans={};routeOverrides={};routeExecutions={};routeArchives=[];warehouseReservations={};persistOrders();persistRouteAssignments();persistRouteDrivers();persistRouteLocks();persistRoutes();persistRouteOverrides();persistRouteExecutions();persistRouteArchives();persistWarehouseReservations();renderAll()};


