  reportingData=normalizeReportingData({settings:{dateBasis:'deliveryDate',costMethod:'smart',includeDeliveryRevenue:true,includeDriverCosts:true,payrollContribPct:30,revenueTaxPct:6},employees:demoEmployees,expenses:[...monthlyExpenses,...oneTimeExpenses]});

  // Reservations for pickup-ready orders.
  for(const order of pickupReadyOrders)warehouseReservations[order.id]={orderId:order.id,createdAt:isoAt(0,8),lines:stockLinesFromItems(order.items),demoTag:DEMO_TAG};

  // Create three operational routes: ready to depart, in transit and awaiting closure.
  const readyPool=activeDeliveryOrders.filter(o=>o.fulfillmentStatus==='active'&&orderReady(o));
  const todayRoutePool=readyPool.filter(o=>o.deliveryDate===dayISO(0));
  const tomorrowRoutePool=readyPool.filter(o=>o.deliveryDate===dayISO(1));
  const operationalDrivers=demoDrivers.slice(0,-2).filter(driver=>driver.active);
  const fittingDriver=(list,excludedIds=new Set())=>operationalDrivers.filter(driver=>!excludedIds.has(driver.id)).map(driver=>({driver,fit:driverFitForRoute(driver,list)})).filter(item=>!item.fit.hasData||item.fit.fits).sort((a,b)=>driverSuitabilityScore(a.driver,a.fit)-driverSuitabilityScore(b.driver,b.fit))[0]?.driver||null;
  const readyRouteOrders=[];for(const order of tomorrowRoutePool){if(readyRouteOrders.length>=4)break;const candidate=[...readyRouteOrders,order];if(fittingDriver(candidate))readyRouteOrders.push(order)}
