s=routeRuleMetrics(plan,list.length);routePlans[routeId]=plan;routeDriverAssignments[routeId]=driver.id;routeOverrides[routeId]={routeMode:'round',driverPaymentMode:'auto',manualDriverPayment:0,approved:false,approvalNote:'',approvedAt:''};if(state!=='ready')routeExecutions[routeId]={id:routeId,status:state,departedAt:isoAt(0,9),returnedAt:state==='awaiting_close'?isoAt(0,17):'',routeTitle:meta.title,date:routeDate,routeMode:'round',driverId:driver.id,driverSnapshot:cloneValue(driver),orderIds:list.map(o=>o.id),planSnapshot:compactRoutePlanSnapshot(plan),outcomes:{},actualKm:state==='awaiting_close'?Math.round(Number(plan.distance||0)/1000+7):'',note:state==='awaiting_close'?'Водитель вернулся, результаты точек ещё не внесены':''}
