  persistSettings();persistProducts();persistInventoryMovements();persistDrivers();persistOrders();persistRoutes();persistRouteAssignments();persistRouteDrivers();persistRouteLocks();persistRouteOverrides();persistRouteExecutions();persistRouteArchives();persistWarehouseReservations();persistReporting();
