/* ===== END ISOLATED PROGRAM DEMONSTRATION ===== */

function auditDemonstrationScenario(){
  const errors=[],orderIds=orders.map(o=>o.id),productIds=new Set(products.map(p=>p.id)),driverIds=new Set(drivers.map(d=>d.id));
  if(orders.length!==70)errors.push(`ожидалось 70 заказов, найдено ${orders.length}`);
  if(new Set(orderIds).size!==orderIds.length)errors.push('обнаружены повторяющиеся идентификаторы заказов');
  if(drivers.length!==18||driverIds.size!==drivers.length)errors.push('список водителей сформирован некорректно');
  if(!products.length||productIds.size!==products.length)errors.push('каталог товаров сформирован некорректно');
  if(reportingData.employees.length!==12)errors.push('не сформирован штат из 12 сотрудников');
  if(reportingData.expenses.length!==22)errors.push('не сформированы 22 статьи расходов');
  const requiredStatuses=['active','picking','pickup_ready','in_transit','awaiting_close','delivered','partial','not_delivered','pickup_collected','not_relevant'];
  for(const status of requiredStatuses)if(!orders.some(o=>o.fulfillmentStatus===status))errors.push(`отсутствует сценарий статуса «${fulfillmentLabel(status)}»`);
  if(!orders.some(o=>o.orderType==='delivery')||!orders.some(o=>o.orderType==='pickup'))errors.push('не созданы оба способа получения: доставка и самовывоз');
  if(!orders.some(o=>o.paymentStatus==='paid')||!orders.some(o=>o.paymentStatus==='pending'))errors.push('не созданы оплаченные и ожидающие оплаты заказы');
  if(!orders.some(o=>o.deliveryCostManual))errors.push('не создан сценарий ручной стоимости доставки');
  if(!orders.some(o=>asArray(o.deliveryAttempts).length))errors.push('не создана история попыток доставки');
  if(!Object.keys(warehouseReservations).length)errors.push('не создан резерв товара для самовывоза');
  const routeIds=new Set(Object.keys(routeCatalog));
  for(const [orderId,routeId] of Object.entries(routeAssignments))if(routeId!=='__unassigned__'&&(!orderIds.includes(orderId)||!routeIds.has(routeId)))errors.push(`повреждено назначение рейса ${routeId}`);
  for(const [routeId,driverId] of Object.entries(routeDriverAssignments))if(!routeIds.has(routeId)||!driverIds.has(driverId))errors.push(`повреждено назначение водителя в рейсе ${routeId}`);
  for(const execution of Object.values(routeExecutions))if(!asArray(execution.orderIds).length||asArray(execution.orderIds).some(id=>!orderIds.includes(id)))errors.push('активный рейс содержит недействительный заказ');
  if(!Object.values(routeExecutions).some(x=>x.status==='in_transit'))errors.push('не создан рейс в пути');
  if(!Object.values(routeExecutions).some(x=>x.status==='awaiting_close'))errors.push('не создан рейс на закрытии');
  const readyRoute=routePlans['demo-route-ready'],readyDriver=drivers.find(d=>d.id===routeDriverAssignments['demo-route-ready']),readyOrders=asArray(readyRoute?.orderedIds).map(id=>orders.find(o=>o.id===id)).filter(Boolean);
  if(!readyRoute||!readyOrders.length||!readyDriver||!driverFitForRoute(readyDriver,readyOrders).fits)errors.push('не создан исправный рейс, готовый к выезду');
  if(!routeArchives.length)errors.push('не создан архив закрытых рейсов');
  if(!reportingData.employees.some(x=>x.enabled!==false)||!reportingData.expenses.some(x=>x.enabled!==false))errors.push('финансовый сценарий не содержит действующих сотрудников или расходов');
  if(!inventoryMovements.some(x=>x.type==='receipt')||!inventoryMovements.some(x=>x.type==='expense')||!inventoryMovements.some(x=>x.type==='writeoff'))errors.push('неполная история движения склада');
  for(const product of products){const stock=productStockOnHand(product);if(!Number.isFinite(stock)||stock<0)errors.push(`некорректный остаток товара ${product.article||product.name}`)}
  return{ok:!errors.length,errors,summary:{orders:orders.length,products:products.length,drivers:drivers.length,routes:Object.keys(routeCatalog).length,archives:routeArchives.length,employees:reportingData.employees.length,expenses:reportingData.expenses.length}}
}

function syncDemonstrationModeUI(){
  const active=isDemonstrationMode();
  document.body?.classList.toggle('demo-mode',active);
  const toggle=$('demoModeToggle'),label=$('demoModeToggleLabel'),status=$('demoModeStatus'),restart=$('restartDemoButton');
  if(toggle)toggle.checked=active;
  if(label)label.textContent=active?'Включена':'Выключена';
  if(restart)restart.style.display=active?'inline-flex':'none';
  if(status){status.classList.toggle('active',active);status.textContent=active?`Демонстрация включена: ${orders.length.toLocaleString('ru-RU')} заказов, ${products.length.toLocaleString('ru-RU')} товаров, ${drivers.length.toLocaleString('ru-RU')} водителей, ${Object.keys(routeCatalog).length.toLocaleString('ru-RU')} рабочих рейсов. Все изменения изолированы от основной базы.`:'Демонстрация выключена. Программа работает с основной базой.'}
}

async function requestDemonstrationMode(enabled){
  const toggle=$('demoModeToggle');
  if(enabled===isDemonstrationMode()){syncDemonstrationModeUI();return}
  if(enabled){
    if(!await jfConfirm('Включить демонстрацию программы?\n\nОткроется отдельная учебная база с заказами, складом, рейсами, водителями и отчётностью. Основная база останется без изменений.')){if(toggle)toggle.checked=false;return}
    try{window.TeplitsaWarehouseBootstrap?window.TeplitsaWarehouseBootstrap.setDemo(true):localStorage.setItem(DEMO_MODE_FLAG_KEY,'1');createDemonstrationScenario({showMessage:false});showView('orders');alert('Демонстрация включена. Учебная база создана и прошла автоматическую проверку. Основные данные защищены и не изменялись.')}catch(err){console.error('Ошибка запуска демонстрации',err);window.TeplitsaWarehouseBootstrap?window.TeplitsaWarehouseBootstrap.setDemo(false):localStorage.removeItem(DEMO_MODE_FLAG_KEY);localStorage.removeItem(resolveDataStorageKey('scenario_version'));alert('Не удалось включить демонстрацию: '+(err?.message||err)+'. Основная база не изменена.');location.reload()}
    return
  }
  if(!await jfConfirm('Выключить демонстрацию и вернуться к основной базе?\n\nВсе изменения учебного сценария останутся только в демонстрационной среде и не будут перенесены в рабочие данные.')){if(toggle)toggle.checked=true;return}
  window.TeplitsaWarehouseBootstrap?window.TeplitsaWarehouseBootstrap.setDemo(false):localStorage.removeItem(DEMO_MODE_FLAG_KEY);location.reload()
}

async function restartDemonstrationScenario(){
  if(!isDemonstrationMode())return;
  if(!await jfConfirm('Запустить демонстрацию заново?\n\nТекущие изменения учебной базы будут удалены и заменены полным исходным сценарием. Основная база не затрагивается.'))return;
  try{createDemonstrationScenario({showMessage:true});showView('orders')}catch(err){alert('Не удалось пересоздать учебный сценарий: '+(err?.message||err))}
}

