  if(driverIsAggregator(driver)){if(cfg.pricingMode==='quote')return'Фактическая цена заявки · сумма и номер заказа фиксируются в рейсе';if(cfg.baseAmount)parts.push(`подача ${money(cfg.baseAmount)}`);if(cfg.distanceRate)parts.push(`${cfg.distanceRate.toLocaleString('ru-RU')} ₽/км`);if(cfg.stopRate)parts.push(`${cfg.stopRate.toLocaleString('ru-RU')} ₽/точка`);if(cfg.serviceFeePct)parts.push(`надбавка ${cfg.serviceFeePct.toLocaleString('ru-RU')}%`);if(cfg.minimumAmount)parts.push(`минимум ${money(cfg.minimumAmount)}`);return parts.join(' + ')||'Расчётный тариф не заполнен'}
