  const add=(ok,label,reason='',action='')=>{const passed=Boolean(ok),failureReason=passed?'':String(reason||''),failureAction=passed?'':String(action||'');checks.push({ok:passed,label,reason:failureReason,action:failureAction});if(!passed&&failureReason)reasons.push(failureReason)};
